// Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
//
// The page: generates this visitor's keys in the browser (worker.js), uploads
// only the context, public and evaluation keys, then for each question
// encrypts the form locally, sends the ciphertext, and decrypts the reply.
// The measurements, the secret key and the score never leave this browser.

const worker = new Worker("worker.js", { type: "module" });
let nextId = 0;
const pending = new Map();
worker.onmessage = ({ data: { id, result, error } }) => {
  const p = pending.get(id);
  pending.delete(id);
  error ? p.reject(new Error(error)) : p.resolve(result);
};
const call = (op, args = [], transfer = []) =>
  new Promise((resolve, reject) => {
    const id = nextId++;
    pending.set(id, { resolve, reject });
    worker.postMessage({ id, op, args }, transfer);
  });

// A fresh random session per page load: its own keys, folder and trace on the service.
const session = Array.from(crypto.getRandomValues(new Uint8Array(16)),
  (b) => b.toString(16).padStart(2, "0")).join("");
const api = (path) => `/s/${session}/${path}`;

const $ = (id) => document.getElementById(id);
const status = (msg) => { $("status").textContent = msg; };
const mb = (n) => `${(n / 1e6).toFixed(1)} MB`;
const sent = [];
const logSent = (what, n) => {
  sent.push(`${what}: ${mb(n)}`);
  $("sent").textContent = sent.join("\n");
};

function band(r) {
  const p = r * 100;
  return p < 10 ? "low" : p < 20 ? "intermediate" : "high";
}

function readForm() {
  return [
    $("sex").value === "m",
    Number($("age").value), Number($("bmi").value), Number($("sbp").value),
    $("treated").checked ? 1 : 0, $("smoker").checked ? 1 : 0, $("diabetic").checked ? 1 : 0,
  ];
}

async function setup() {
  status("Generating your keys in this browser (a few seconds)…");
  let t = performance.now();
  const files = await call("keygen");
  const keygenS = ((performance.now() - t) / 1000).toFixed(1);
  let total = 0;
  for (const [name, bytes] of Object.entries(files)) {
    status(`Keys ready in ${keygenS}s. Sending ${name} (${mb(bytes.length)}) to the risk service, once…`);
    const r = await fetch(api(`setup/${name}`), { method: "PUT", body: bytes });
    if (!r.ok) throw new Error(`upload of ${name} failed (${r.status})`);
    logSent(`setup ${name}`, bytes.length);
    total += bytes.length;
  }
  status(`Ready. Your keys were made here in ${keygenS}s; ${mb(total)} of public keys sent once.`);
  $("go").disabled = false;
}

async function score(ev) {
  ev.preventDefault();
  const args = readForm();
  const why = await call("check", args);
  if (why) { status(`Not sent: ${why}.`); return; }
  $("go").disabled = true;
  try {
    status("Encrypting in this browser…");
    const ct = await call("encrypt", args);
    const n = ct.length;
    status(`Sending ${mb(n)} of ciphertext…`);
    const t = performance.now();
    const r = await fetch(api("score"), { method: "POST", body: ct });
    if (!r.ok) throw new Error(`scoring failed (${r.status})`);
    const reply = await r.arrayBuffer();
    const secs = ((performance.now() - t) / 1000).toFixed(1);
    logSent("question (encrypted)", n);
    const risk = await call("decrypt", [reply], [reply]);
    $("risk").textContent = `${(risk * 100).toFixed(2)}%`;
    $("band").textContent = band(risk);
    $("band").className = `band ${band(risk)}`;
    $("result").hidden = false;
    status(`Scored blind by the service in ${secs}s, decrypted here. Change any answer and calculate again.`);
  } catch (e) {
    status(`Something went wrong: ${e.message}`);
  } finally {
    $("go").disabled = false;
  }
}

$("form").addEventListener("submit", score);
setup().catch((e) => status(`Setup failed: ${e.message}`));
